# Add timeout to all fetch calls
async def fetch_with_timeout(url: str, timeout_ms: int = 8000, **kwargs):
    import asyncio
    try:
        return await asyncio.wait_for(
            fetch(url, **kwargs),
            timeout=timeout_ms / 1000
        )
    except asyncio.TimeoutError:
        raise TimeoutError(f"Request to {url} exceeded {timeout_ms}ms timeout")

